function safeStr(v) { return v === null || v === undefined ? '' : String(v).trim(); }
function safeBool(v) {
  if (v === true) return true;
  if (typeof v === 'string') return v.trim().toLowerCase() === 'true';
  return false;
}
function hasValidJson(v) {
  const s = safeStr(v);
  if (!s || s === '{}' || s === 'null') return false;
  try {
    const p = JSON.parse(s);
    return p && typeof p === 'object' && !Array.isArray(p);
  } catch (e) { return false; }
}

const MAX_VORGAENGE = 100;
const allRows = $input.all().map(i => i.json || {});
const rows = [...allRows].sort((a, b) => {
  const ad = Date.parse(a.firstseen || a.createdAt || '') || 0;
  const bd = Date.parse(b.firstseen || b.createdAt || '') || 0;
  return bd - ad;
}).slice(0, MAX_VORGAENGE);
const total = rows.length;

function countIf(fn) { return rows.filter(fn).length; }

function isNextcloudDone(r) {
  const f = safeStr(r.nextcloudFolder);
  return !!(f && f.toLowerCase() !== 'null' && f !== '-');
}
function isBewertungDone(r) {
  return safeStr(r.summaryText).length >= 50 &&
    hasValidJson(r.analysisJson) &&
    safeStr(r.lastAnalysisAt).length > 0;
}
const nextcloudDone = countIf(isNextcloudDone);
const bewertungDone = countIf(isBewertungDone);

// FIX 2026-07-25: contentCreatedAt wird von P4 bei JEDEM Versuch gesetzt (Erfolg UND
// Fehlschlag) und sagt nichts darueber aus, ob echter Satire-Content erzeugt wurde - ersetzt
// durch eine ehrliche Reaktion-Stufe, die tatsaechlichen Content prueft.
// P5/P6/P8/P8b/P9 (Visual/Bild/diePARTEI/Mastodon) laufen tatsaechlich nur fuer die
// Sharepic-Kohorte (sharepicNeedStage=topic_ok) - dafuer bleibt sharepicTotal richtig.
// FIX 2026-07-26: P4 (Reaktion/Text) ist KEIN Teil dieser Kohorte - die Text-Reaktion
// entsteht laut P4 ("Pruefe Content-Freigabe") fuer topic_ok UND fuer not_applicable/
// topic_error gleichermassen, nur watching/ignored/noch-nicht-bewertete Vorgaenge bekommen
// nie eine Reaktion. Bisher zeigte das Dashboard z.B. "5/6" (nur die Sharepic-Kohorte)
// statt der tatsaechlich richtigen Zahl gegen alle Reaktion-faehigen Vorgaenge - Realfall
// 2026-07-26 vom Nutzer bemerkt ("muesste man das nicht 5/30 sehen?").
const sharepicWanted = rows.filter(r => safeStr(r.sharepicNeedStage) === 'topic_ok');
const sharepicTotal = sharepicWanted.length;
function countIfWanted(fn) { return sharepicWanted.filter(fn).length; }

const REAKTION_EXCLUDED_STAGES = new Set(['watching', 'ignored', '']);
const contentEligible = rows.filter(r => isBewertungDone(r) && !REAKTION_EXCLUDED_STAGES.has(safeStr(r.contentStage)));
const contentEligibleTotal = contentEligible.length;
function countIfContentEligible(fn) { return contentEligible.filter(fn).length; }

function isReaktionDone(r) { return safeStr(r.websiteArticle).length > 20 || safeStr(r.pressStatement).length > 20; }
function isVisualPromptDone(r) { return safeStr(r.imagePrompt).length > 0; }
function isBildDone(r) { return safeStr(r.imageFinalPath).length > 0; }
const reaktionDone = countIfContentEligible(isReaktionDone);
const p2Done = countIfWanted(isVisualPromptDone);
const p3Done = countIfWanted(isBildDone);

const wordpressDone = countIf(r => safeBool(r.wordpressPosted));
const wordpressGoslarDone = countIf(r => safeBool(r.wordpressGoslarPosted));
// 2026-07-26: P8 legt seitdem sofort Entwuerfe an, ein separater taeglicher Schritt
// (P8b) veroeffentlicht davon nur einen pro Tag - Entwurf != veroeffentlicht, beides
// getrennt sichtbar machen statt wie bisher nur 'fertig'/'fehlt'.
// FIX 2026-07-26: P8/P8b/P9 sind (P9 seit heute) NICHT auf die Sharepic-Kohorte beschraenkt -
// alle drei verlangen nur echten P4-Content (websiteArticle/instagramCaption), warten auf ein
// Bild nur zusaetzlich bei topic_ok. Denominator ist reaktionDone (wer echten Content hat, kann
// hier ankommen), nicht sharepicTotal - gleiche Korrektur wie bei P4 oben.
const wordpressGoslarDraftDone = countIfContentEligible(r => safeStr(r.wordpressGoslarDraftId).length > 0 && !safeBool(r.wordpressGoslarPosted));
const mastodonDone = countIfContentEligible(r => safeBool(r.mastodonPosted));
const paperlessDone = countIf(r => safeStr(r.paperlessBackfilledAt).length > 0);

function esc(s) {
  return safeStr(s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function pct(n, denom) { denom = denom === undefined ? total : denom; return denom > 0 ? Math.round((n / denom) * 100) : 0; }

function stageRow(label, done, denom, schedule) {
  denom = denom === undefined ? total : denom;
  return '<tr><td>' + esc(label) + '</td><td class="schedule">' + esc(schedule || '') + '</td><td>' + done + ' / ' + denom + '</td><td>' +
    '<div class="bar"><div class="fill" style="width:' + pct(done, denom) + '%"></div></div>' +
    '</td><td class="pct">' + pct(done, denom) + '%</td></tr>';
}

// Detailtabelle 2026-07-25 (Nutzerwunsch): eine Zeile pro Vorgang (nur die, die tatsaechlich
// in Nextcloud existieren - nextcloudFolder gesetzt), Status jeder Stufe nebeneinander als
// Spalte. topic_ok-Vorgaenge (die, die DIE PARTEI tatsaechlich kommentiert) stehen oben und
// sind hervorgehoben, weil das der eigentlich interessante Teil der Pipeline ist - fuer alle
// anderen sind Reaktion/Visual/Bild/diePARTEI/Mastodon nicht zutreffend (na), nicht "fehlend".
function statusCell(state) {
  if (state === 'done') return '<td class="cell-done">✓</td>';
  if (state === 'draft') return '<td class="cell-draft">◐</td>';
  if (state === 'na') return '<td class="cell-na">–</td>';
  return '<td class="cell-pending">·</td>';
}

function detailRow(r) {
  const decided = safeStr(r.sharepicNeedStage).length > 0;
  const wantsSharepic = safeStr(r.sharepicNeedStage) === 'topic_ok';
  const nc = isNextcloudDone(r) ? 'done' : 'pending';
  const bw = isBewertungDone(r) ? 'done' : 'pending';
  const sp = !decided ? 'pending' : (wantsSharepic ? 'done' : 'na');
  // FIX 2026-07-26: Reaktion (Text) ist nicht auf die Sharepic-Kohorte beschraenkt, siehe oben.
  const contentEligibleRow = isBewertungDone(r) && !REAKTION_EXCLUDED_STAGES.has(safeStr(r.contentStage));
  const rk = !contentEligibleRow ? 'na' : (isReaktionDone(r) ? 'done' : 'pending');
  const vp = !wantsSharepic ? 'na' : (isVisualPromptDone(r) ? 'done' : 'pending');
  const bd = !wantsSharepic ? 'na' : (isBildDone(r) ? 'done' : 'pending');
  const wp = safeBool(r.wordpressPosted) ? 'done' : 'pending';
  const wg = !wantsSharepic ? 'na' : (safeBool(r.wordpressGoslarPosted) ? 'done' : (safeStr(r.wordpressGoslarDraftId).length > 0 ? 'draft' : 'pending'));
  const md = !wantsSharepic ? 'na' : (safeBool(r.mastodonPosted) ? 'done' : 'pending');
  const pl = safeStr(r.paperlessBackfilledAt).length > 0 ? 'done' : 'pending';
  return '<tr class="' + (wantsSharepic ? 'row-sharepic' : '') + '"><td>' + esc(r.vorgangsnummer) + '</td><td>' + esc(r.title).slice(0, 70) + '</td>' +
    statusCell(nc) + statusCell(bw) + statusCell(sp) + statusCell(rk) + statusCell(vp) + statusCell(bd) + statusCell(wp) + statusCell(wg) + statusCell(md) + statusCell(pl) +
    '</tr>';
}

const detailCandidates = rows.filter(isNextcloudDone).sort((a, b) => {
  const aWant = safeStr(a.sharepicNeedStage) === 'topic_ok' ? 1 : 0;
  const bWant = safeStr(b.sharepicNeedStage) === 'topic_ok' ? 1 : 0;
  if (aWant !== bWant) return bWant - aWant;
  const ad = Date.parse(a.lastseen || a.firstseen || '') || 0;
  const bd = Date.parse(b.lastseen || b.firstseen || '') || 0;
  return bd - ad;
});

const now = new Date().toLocaleString('de-DE', { timeZone: 'Europe/Berlin' });

const html = '<!DOCTYPE html>' +
'<html lang="de">' +
'<head>' +
'<meta charset="utf-8">' +
'<title>ALLRIS Status-Uebersicht</title>' +
'<style>' +
'  body { font-family: -apple-system, Segoe UI, Arial, sans-serif; background:#0f1115; color:#e6e6e6; margin:0; padding:32px; }' +
'  h1 { font-size:20px; margin-bottom:4px; }' +
'  .meta { color:#9aa0a6; font-size:13px; margin-bottom:24px; }' +
'  table { border-collapse: collapse; width:100%; margin-bottom:32px; }' +
'  th, td { text-align:left; padding:8px 12px; border-bottom:1px solid #2a2d34; font-size:14px; }' +
'  th { color:#9aa0a6; font-weight:600; font-size:12px; text-transform:uppercase; letter-spacing:0.04em; }' +
'  .bar { background:#2a2d34; border-radius:4px; height:8px; width:160px; overflow:hidden; }' +
'  .fill { background:#5b8def; height:100%; }' +
'  .pct { color:#9aa0a6; width:48px; }' +
'  .schedule { color:#9aa0a6; font-size:12px; white-space:nowrap; }' +
'  .detail-table th, .detail-table td { text-align:center; padding:6px 8px; font-size:13px; }' +
'  .detail-table th:nth-child(1), .detail-table td:nth-child(1), .detail-table th:nth-child(2), .detail-table td:nth-child(2) { text-align:left; }' +
'  .detail-table td:nth-child(2) { color:#c9ccd1; }' +
'  .cell-done { color:#4caf50; font-weight:600; }' +
'  .cell-na { color:#4a4d54; }' +
'  .cell-pending { color:#f2b950; }' +
'  .cell-draft { color:#5b8def; font-weight:600; }' +
'  tr.row-sharepic { background:#181c24; }' +
'  .empty { color:#5f6368; font-style:italic; }' +
'  h2 { font-size:15px; margin-top:8px; margin-bottom:8px; color:#e6e6e6; }' +
'  .hint { color:#f2b950; font-size:12px; margin-bottom:12px; }' +
'</style>' +
'</head>' +
'<body>' +
'  <h1>ALLRIS Pipeline &mdash; Status-Uebersicht</h1>' +
'  <div class="meta">Stand: ' + now + ' &middot; ' + (allRows.length > MAX_VORGAENGE ? ('neueste ' + total + ' von ' + allRows.length + ' Vorgaengen') : (total + ' Vorgaenge insgesamt')) + '</div>' +
'  <table>' +
'    <thead><tr><th>Stufe</th><th>Laeuft an</th><th>Fertig</th><th></th><th></th></tr></thead>' +
'    <tbody>' +
       stageRow('P1: Vorgaenge angelegt (Ingestion)', total, undefined, 'alle 5h, :05') +
       stageRow('P2: Nextcloud (Dokumente hochgeladen)', nextcloudDone, undefined, 'alle 5h, :15') +
       stageRow('P3: Bewertung (Summary + Analyse)', bewertungDone, undefined, 'stuendlich, :05') +
       stageRow('P3d: Sharepic gewuenscht (Eignungs-Agent)', sharepicTotal, undefined, 'stuendlich, :13') +
       stageRow('P4: Reaktion erzeugt (Satire-Content)', reaktionDone, contentEligibleTotal, 'stuendlich, :21') +
       stageRow('P5: Visual Prompt vorhanden', p2Done, sharepicTotal, 'stuendlich, :29') +
       stageRow('P6: Bild fertig', p3Done, sharepicTotal, 'stuendlich, :37') +
       stageRow('P7: WordPress golietz.de veroeffentlicht', wordpressDone, undefined, 'stuendlich, :45') +
       stageRow('P8: WordPress diePARTEI Entwurf angelegt', wordpressGoslarDraftDone, reaktionDone, 'stuendlich, :52') +
       stageRow('P8b: WordPress diePARTEI veroeffentlicht', wordpressGoslarDone, reaktionDone, 'taeglich, 06:00') +
       stageRow('P9: Mastodon veroeffentlicht', mastodonDone, reaktionDone, 'taeglich, 17:30') +
       stageRow('Paperless archiviert', paperlessDone, undefined, 'stuendlich, :00') +
'    </tbody>' +
'  </table>' +
'  <h2>Alle Vorgaenge im Detail (nur was in Nextcloud existiert, topic_ok oben)</h2>' +
'  <div class="hint">' + detailCandidates.length + ' Vorgaenge mit Nextcloud-Ordner. ✓ fertig · ◐ Entwurf angelegt (wartet auf taegliche Veroeffentlichung) · · noch offen · – nicht zutreffend (kein Sharepic gewuenscht). Zeilen mit hellerem Hintergrund = topic_ok (wird von DIE PARTEI kommentiert).</div>' +
'  <table class="detail-table">' +
'    <thead><tr><th>Vorgangsnummer</th><th>Titel</th><th>Nextcloud</th><th>Bewertung</th><th>Sharepic</th><th>Reaktion</th><th>Visual</th><th>Bild</th><th>golietz.de</th><th>diePARTEI</th><th>Mastodon</th><th>Paperless</th></tr></thead>' +
'    <tbody>' +
       detailCandidates.map(detailRow).join('\n') +
'    </tbody>' +
'  </table>' +
'</body>' +
'</html>';

return [{ json: { html: html } }];
